//! Byte-for-byte fixtures generated by the PHP package.
//! The captured IANA 2026f zoneinfo keeps aliases and transition flags identical
//! to the PHP run, independently of the host OS's timezone data.

use serde_json::Value;
use spatie_calendar_links::{
    Ics, IcsOptions, Link, Presentation, Reminder,
    generators::{Service, WebGenerator},
    jiff::{fmt::temporal::DateTimeParser, tz::TimeZoneDatabase},
};

fn zoned(value: &str, database: &TimeZoneDatabase) -> jiff::Zoned {
    if value.ends_with(']') {
        DateTimeParser::new()
            .parse_zoned_with(database, value)
            .unwrap()
    } else {
        format!("{value}[{}]", &value[value.len() - 6..])
            .parse()
            .unwrap()
    }
}

fn string(value: &Value) -> Option<String> {
    value.as_str().map(str::to_owned)
}

#[test]
fn matches_php_generated_output() {
    let database = TimeZoneDatabase::from_dir(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/fixtures/zoneinfo"
    ))
    .unwrap();
    let cases: Value = serde_json::from_str(include_str!("fixtures/php.json")).unwrap();
    for case in cases.as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let from = zoned(case["from"].as_str().unwrap(), &database);
        let mut link = if let Some(days) = case["days"].as_u64() {
            Link::create_all_day(
                case["title"].as_str().unwrap(),
                from,
                u32::try_from(days).unwrap(),
            )
            .unwrap()
        } else {
            Link::create(
                case["title"].as_str().unwrap(),
                from,
                zoned(case["to"].as_str().unwrap(), &database),
            )
            .unwrap()
        }
        .description(case["description"].as_str().unwrap_or(""))
        .address(case["address"].as_str().unwrap_or(""));
        if let Some(guests) = case["guests"].as_array() {
            for guest in guests {
                link = link
                    .guest(guest[0].as_str().unwrap(), guest[1].as_bool().unwrap())
                    .unwrap();
            }
        }
        for (key, service) in [
            ("google", Service::Google),
            ("yahoo", Service::Yahoo),
            ("web_outlook", Service::WebOutlook),
            ("web_office", Service::WebOffice),
        ] {
            let mut generator = WebGenerator::new(service);
            if let Some(parameters) = case["parameters"].as_array() {
                for parameter in parameters {
                    generator.url_parameters.push((
                        parameter[0].as_str().unwrap().to_owned(),
                        string(&parameter[1]),
                    ));
                }
            }
            assert_eq!(
                link.format_with(&generator).unwrap(),
                case["expected"][key].as_str().unwrap(),
                "{name}: {key}"
            );
        }
        let options = &case["options"];
        let generator = Ics {
            options: IcsOptions {
                uid: string(&options["UID"]),
                prodid: string(&options["PRODID"]),
                url: string(&options["URL"]),
                dtstamp: options["DTSTAMP"].as_str().map(|s| s.parse().unwrap()),
                rrule: string(&options["RRULE"]),
                transparency: string(&options["TRANSP"]),
                class: string(&options["CLASS"]),
                microsoft_busy_status: string(&options["X-MICROSOFT-CDO-BUSYSTATUS"]),
                reminder: options.get("REMINDER").map(|r| Reminder {
                    description: string(&r["DESCRIPTION"]),
                    time: r["TIME"].as_str().map(|s| s.parse().unwrap()),
                }),
            },
            presentation: Presentation::File,
            ..Ics::default()
        };
        assert_eq!(
            link.format_with(&generator).unwrap(),
            case["expected"]["ics"].as_str().unwrap(),
            "{name}: ics"
        );
        assert_eq!(
            link.format_with(&Ics {
                presentation: Presentation::Html,
                ..generator.clone()
            })
            .unwrap(),
            case["expected"]["ics_uri"].as_str().unwrap(),
            "{name}: uri"
        );
        assert_eq!(
            link.format_with(&Ics {
                with_timezones: true,
                ..generator
            })
            .unwrap(),
            case["expected"]["ics_with_timezones"].as_str().unwrap(),
            "{name}: named"
        );
    }
}
